from common import *
import shutil,platform,importlib.metadata

def main():
    assert not BASE.exists()
    import qlib, pandas as pd,lightgbm,numpy
    assert Path(qlib.__file__).resolve().is_relative_to(ROOT)
    qlib.init(provider_uri=str(PROVIDER),region='cn',kernels=1)
    from qlib.data import D
    version=str(pd.Timestamp(D.calendar(start_time='2020-01-01')[-1]).date())
    assert version=='2026-11-03'
    prior=read(PRIOR/'configs/frozen-study.json')
    prepared=read(PRIOR/'docs/prepared-labels.json')
    for name in ['feature_manifest','prior_H20_labels','validation_manifest']:check(prepared[name])
    files=[FEATURE,OLD_LABEL,VALID,DATES,WEIGHTS,PRIOR/'docs/prepared-labels.json',PRIOR/'docs/inputs-h20.json',PRIOR/'docs/sources-h20.json',PRIOR/'docs/H20-input-bridge.json',PRIOR/'configs/frozen-study.json',PROVIDER/'calendars/day.txt',ROOT/'scripts/data_collector/tushare/st_daily.csv']
    for b in prepared['horizons']['20']['blocks']:check(b);files.append(ROOT/b['path'])
    for m in read(PRIOR/'docs/sources-h20.json')['components']:check(m['model']);files.append(ROOT/m['model']['path'])
    for rel in ['backtest/models/regime_adapt.py','backtest/models/rankic_early_stop.py','backtest/scripts/train/train_regime_arm.py','backtest/scripts/evaluate/eval_ic_multi_pool.py','backtest/scripts/evaluate/ensemble_preds.py','backtest/scripts/prepare/prepare_regime_train_chunks.py']:
        files.append(ROOT/rel)
    for part in ['configs','docs','metrics','data','reports','source-records']:(BASE/part).mkdir(parents=True,exist_ok=True)
    shutil.copy2(PRIOR/'configs/evaluation.yaml',BASE/'configs/evaluation.yaml')
    shutil.copy2(TMP/'label-preflight.json',BASE/'docs/label-preflight.json')
    env={'python':sys.version,'executable':sys.executable,'platform':platform.platform(),'git_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'packages':{n:importlib.metadata.version(n) for n in ['numpy','pandas','lightgbm','scipy','pyqlib']},'modules':{n:str(m.__file__) for n,m in [('numpy',numpy),('lightgbm',lightgbm),('qlib',qlib)]},'lightgbm_binaries':[fingerprint(p) for p in Path(lightgbm.__file__).parent.rglob('*') if p.suffix in ['.dylib','.so']]}
    write(BASE/'docs/environment.json',env)
    study={'hypothesis':'Daily label grading suppresses irrelevant fine rank differences while preserving or improving predictive usefulness; robustness and return are assessed separately.','user_idea':'标签分级实验：等样本、等涨幅、两头少中间多，并尝试不同n。','user_control_choice':'沿用最近 H20／patience50 对照','formal_baseline':'regime-adapt/m0-h20-t5h5-es-v1','paired_control':'training-target/horizon-style-p50-20261105-v1/arms/h20','seeds':SEEDS,'parameters':prior['parameters'],'train_window':['2004-01-02','2020-07-31'],'eval_window':['2020-08-03','2026-07-31'],'es_metric':'top5_h5_net_ann','valid_cutoff':'2026-07-23','data_version':version,'source_snapshots':{'features':'2026-11-02 frozen features','reference_labels':'2026-11-03 frozen H20 labels','perturbed_labels':'2026-11-02 frozen H20 labels;106 normalized differences','evaluation':'2026-11-03 frozen provider'},'candidates':[{'id':'quantile5','bins':5,'method':'fixed daily percentile boundaries 20/40/60/80; retain ties'},{'id':'quantile10','bins':10,'method':'fixed daily percentile boundaries10..90; retain ties'},{'id':'width5','bins':5,'method':'raw daily H20 minimum..maximum equally spaced into5 intervals; no winsorization; edge belongs to lower interval'},{'id':'tails5','bins':5,'method':'fixed daily percentile boundaries5/20/80/95; mass5/15/60/15/5; retain ties'}],'encoding':'Ordinal bin ID 0..n-1; one affine transform fitted on reference training rows only matches mean/std of continuous control training labels. Same frozen transform for old-label sensitivity; no CSRankNorm or daily reranking after grading.','sample_protocol':'Exact H20 training indices, original rank-before-date-selection and legacy-h40-base-v1; no sample/intersection changes.','evaluation':'Canonical official_head_from_preds; five-seed daily zscore mean, Top3xH5 net_ann/net_ann_vol/net_sharpe, globalH5RankIC, years/styles; retain individual seeds as diagnostics.','sensitivity':'For quantile5/quantile10/tails5 run all5 seeds on both new/old label treatments unless encoded float32 inputs are identical. Width5 lacks frozen old raw-return magnitudes; report that106-change paired sensitivity is unavailable, do not synthesize old returns.','diagnostics':['bin occupancy and label distortion','full early-stop curves and tree counts','Top3/Top5 tie frequency and seed agreement','paired old/new heads and metric differences on common frozen inputs','short-tree and200-round censoring flags'],'decision_rule':'No single automatic pass threshold or promotion. Compare all4 primary candidates to same-source continuous H20; report return,volatility,Sharpe,RankIC separately. Robustness improvement alone is insufficient. Historical selection window, no independent OOS claim.','budget':{'max_scientific_candidates':4,'nominal_primary_fits':20,'conditional_paired_fits':15,'max_model_fits_including_retries':37,'max_wall_hours':8,'concurrency':1},'prior_research_fit_cost':111,'entry_policy':'One new label-grading study; four internal scientific candidates and two sensitivity treatments retain separate identities/results/costs. Native harness parent lifecycle+fit ledger, supplemental internal-candidate ledger; native variant count is not the scientific count.','temporary_directory':str(TMP),'implementation':'Task-local adapters call existing trainer, evaluator, registry and report; no new permanent module or platform structure.'}
    write(BASE/'configs/frozen-study.json',study)
    meta={'schema_version':2,'entity_type':'experiment','kind':'model','track':'all_a','exp_id':EID,'archive_path':str(BASE.relative_to(ROOT)),'experiment_type':'training_target','title':'标签分级 · H20／patience50','change_summary':'固定H20/patience50，将连续训练标签改为等样本5/10档、等涨幅5档或两头少中间多5档；固定五种子。','comparison_baseline':{'ref':study['formal_baseline'],'version':'v2'},'activity':'model_research','role':'experiment','changed_axes':['label_quantization']}
    write(BASE/'metadata.json',meta)
    for p in [TMP/'common.py',TMP/'setup.py',TMP/'label_preflight.py']:save_source(p)
    files += [BASE/'configs/frozen-study.json',BASE/'configs/evaluation.yaml',BASE/'docs/environment.json',BASE/'docs/label-preflight.json',BASE/'docs/adapter-common.json']
    plan={'schema_version':2,'campaign_id':'label-grading-p50-20261106-v1','idea':study['user_idea'],'track':'all_a_model','direction':'training-target','anchor_exp_id':EID,'archive_path':str(BASE.relative_to(ROOT)),'baseline_ref':study['formal_baseline'],'allowed_changes':['label_quantization'],'selection_rule':study['decision_rule'],'data_version':version,'inputs':[str(p) for p in files],'seeds':SEEDS,'budget':{'max_rounds':3,'max_variants':4,'max_attempts_per_variant':2,'max_wall_hours':8,'max_no_new_evidence_rounds':2,'concurrency':1},'execution_budget':{'max_model_fits':37,'new_label_horizons':[20]},'scientific_candidate_count':4,'paired_control':study['paired_control'],'temporary_directory':str(TMP),'known_native_scope_gap':study['entry_policy']}
    write(BASE/'configs/harness-plan.json',plan)
    r=subprocess.run([sys.executable,str(ROOT/'backtest/scripts/maintenance/experiment_harness.py'),'init','--plan',str(BASE/'configs/harness-plan.json')],capture_output=True,text=True,cwd=ROOT)
    if r.returncode:raise RuntimeError(r.stdout+r.stderr)
    write(PROGRESS,{'status':'preparing','scientific_candidates':{v:{'status':'planned','treatments':{}} for v in VARIANTS},'prior_fit_count':111,'jobs':[],'frozen_study':fingerprint(BASE/'configs/frozen-study.json')})
    print(json.dumps({'archive':str(BASE),'state':str(STATE),'data_version':version,'budget':study['budget']},ensure_ascii=False))

if __name__=='__main__':main()
